window.ENTRY_ASSETS["lp-local-llm-v2--claude-opus-5-5-code--1792739067502-juop8"]={"html":"\u003c!doctype html>\n\u003chtml lang=\"ja\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003ctitle>ローカルLLM — AIを、手元で動かす。\u003c/title>\n\u003cmeta name=\"description\" content=\"ローカルLLMを自分のPCや手元の計算機で動かすという選択肢。試す楽しさ、モデルを選ぶ自由、データの扱いを自分で設計できることを紹介します。\">\n\u003clink rel=\"icon\" href=\"data:,\">\n\u003cscript>document.documentElement.classList.add('js');\u003c/script>\n\u003cstyle>\n:root{\n  --bg:#07090d;\n  --s1:#0d1118;\n  --s2:#131923;\n  --line:#232b38;\n  --tx:#eceae3;\n  --mu:#a6aebb;\n  --lime:#c8ff3d;\n  --ora:#ff8a4c;\n  --cyan:#62e3ff;\n  --ease:cubic-bezier(.2,.8,.2,1);\n  --sans:\"Hiragino Kaku Gothic ProN\",\"Hiragino Sans\",\"Yu Gothic UI\",\"Yu Gothic\",\"Meiryo\",\"Noto Sans JP\",system-ui,sans-serif;\n  --mono:ui-monospace,\"SFMono-Regular\",\"Cascadia Mono\",\"Cascadia Code\",Consolas,Menlo,monospace;\n  --wrap:min(1160px, calc(100% - 48px));\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:72px}\nbody{\n  margin:0;background:var(--bg);color:var(--tx);\n  font-family:var(--sans);line-height:1.8;font-size:16px;\n  -webkit-font-smoothing:antialiased;overflow-x:hidden;\n  background-image:\n    radial-gradient(1200px 600px at 85% -10%, rgba(98,227,255,.08), transparent 60%),\n    radial-gradient(900px 500px at -10% 40%, rgba(200,255,61,.05), transparent 60%),\n    linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px);\n  background-size:auto,auto,48px 48px,48px 48px;\n}\na{color:inherit}\n:focus-visible{outline:3px solid var(--lime);outline-offset:3px;border-radius:6px}\n.skip{position:absolute;left:-999px;top:8px;z-index:100;background:var(--lime);color:#0a0c10;padding:8px 14px;border-radius:8px;font-weight:700}\n.skip:focus{left:12px}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n.mono{font-family:var(--mono)}\n\n/* ---------- header ---------- */\n.progress{position:fixed;inset:0 0 auto 0;height:3px;z-index:60;background:linear-gradient(90deg,var(--lime),var(--cyan));transform:scaleX(0);transform-origin:left}\n.bar-top{\n  position:fixed;inset:0 0 auto 0;z-index:50;height:60px;\n  display:flex;align-items:center;justify-content:space-between;gap:16px;\n  padding:0 max(24px, calc((100% - 1160px)/2));\n  transition:background .4s var(--ease), border-color .4s var(--ease);\n  border-bottom:1px solid transparent;\n}\n.bar-top.scrolled{background:rgba(7,9,13,.82);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-color:var(--line)}\n.brand{display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:800;letter-spacing:.02em}\n.brand-mark{width:26px;height:26px;border:2px solid var(--lime);border-radius:6px;position:relative;display:grid;place-items:center}\n.brand-mark::after{content:\"\";width:8px;height:8px;background:var(--lime);border-radius:2px;animation:blink 1.6s steps(2) infinite}\n.brand small{font-family:var(--mono);font-weight:500;color:var(--mu);font-size:.72rem;letter-spacing:.12em}\n@keyframes blink{50%{opacity:.25}}\n.nav{display:flex;align-items:center;gap:4px}\n.nav a{text-decoration:none;font-size:.88rem;color:var(--mu);padding:6px 10px;border-radius:8px;transition:color .25s,background .25s}\n.nav a:hover,.nav a:focus-visible{color:var(--tx);background:rgba(255,255,255,.06)}\n.motion-btn{\n  font:inherit;font-size:.8rem;color:var(--tx);background:var(--s2);border:1px solid var(--line);\n  border-radius:999px;padding:6px 12px;cursor:pointer;display:flex;align-items:center;gap:8px;white-space:nowrap;\n  transition:border-color .25s,background .25s;\n}\n.motion-btn:hover{border-color:var(--lime)}\n.motion-btn .ico{width:10px;height:10px;display:inline-block;border-left:3px solid currentColor;border-right:3px solid currentColor}\n.motion-btn[aria-pressed=\"true\"] .ico{border:0;border-left:9px solid currentColor;border-top:5px solid transparent;border-bottom:5px solid transparent;height:0;width:0}\n.mini-cta{display:none}\n\n/* ---------- hero ---------- */\n.hero{position:relative;min-height:100vh;min-height:100svh;display:flex;align-items:center;padding:84px 0 48px;overflow:hidden;isolation:isolate}\n#field{position:absolute;inset:0;width:100%;height:100%;z-index:-1;opacity:.9}\n.hero::after{content:\"\";position:absolute;inset:auto 0 0 0;height:160px;background:linear-gradient(transparent,var(--bg));z-index:-1}\n.hero-grid{width:var(--wrap);margin:0 auto;display:grid;grid-template-columns:1.15fr .85fr;gap:40px;align-items:center}\n.eyebrow{font-family:var(--mono);font-size:.78rem;letter-spacing:.18em;color:var(--lime);margin:0 0 18px;display:flex;align-items:center;gap:10px}\n.eyebrow::before{content:\"\";width:28px;height:1px;background:var(--lime)}\nh1{margin:0 0 22px;font-size:clamp(2.6rem,6.6vw,5.4rem);line-height:1.08;font-weight:800;letter-spacing:-.01em}\nh1 .ln{display:block;overflow:hidden;padding-bottom:.06em}\nh1 .ln>span{display:inline-block;animation:rise 1.1s var(--ease) both}\nh1 .ln:nth-child(2)>span{animation-delay:.14s}\n@keyframes rise{from{transform:translateY(105%)}to{transform:none}}\n.grad{\n  background:linear-gradient(100deg,var(--lime) 0%,#eaffb0 40%,var(--cyan) 60%,var(--lime) 100%);\n  background-size:250% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;\n  animation:rise 1.1s var(--ease) .14s both, shine 7s linear 1.4s infinite;\n}\n@keyframes shine{to{background-position:-250% 0}}\n.lead{font-size:clamp(1rem,1.5vw,1.12rem);color:#d4d6d8;max-width:34em;margin:0 0 26px;animation:fadeup .9s var(--ease) .35s both}\n@keyframes fadeup{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}\n.pillars{list-style:none;padding:0;margin:0 0 30px;display:flex;flex-wrap:wrap;gap:10px}\n.pillars li{\n  display:flex;align-items:center;gap:8px;padding:8px 14px;border:1px solid var(--line);border-radius:999px;\n  background:rgba(19,25,35,.7);font-size:.9rem;animation:fadeup .8s var(--ease) both;\n  transition:border-color .3s, transform .3s var(--ease);\n}\n.pillars li:nth-child(1){animation-delay:.5s}.pillars li:nth-child(2){animation-delay:.6s}.pillars li:nth-child(3){animation-delay:.7s}\n.pillars li:hover{border-color:var(--lime);transform:translateY(-2px)}\n.pillars b{color:var(--lime);font-family:var(--mono);font-weight:600;font-size:.78rem}\n.cta-row{display:flex;flex-wrap:wrap;gap:12px;animation:fadeup .8s var(--ease) .8s both}\n.cta{\n  position:relative;overflow:hidden;display:inline-flex;align-items:center;gap:12px;\n  background:var(--lime);color:#0a0c10;font-weight:800;text-decoration:none;\n  padding:15px 24px;border-radius:12px;font-size:1rem;\n  box-shadow:0 0 0 0 rgba(200,255,61,.5), 0 10px 40px -10px rgba(200,255,61,.45);\n  transition:transform .3s var(--ease), box-shadow .3s var(--ease);\n}\n.cta::after{content:\"\";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.55) 50%,transparent 70%);transform:translateX(-120%);transition:transform .7s var(--ease)}\n.cta:hover,.cta:focus-visible{transform:translateY(-2px);box-shadow:0 0 0 6px rgba(200,255,61,.15), 0 16px 50px -10px rgba(200,255,61,.6)}\n.cta:hover::after,.cta:focus-visible::after{transform:translateX(120%)}\n.cta .arr{transition:transform .3s var(--ease)}\n.cta:hover .arr,.cta:focus-visible .arr{transform:translateY(3px)}\n.ghost{display:inline-flex;align-items:center;padding:14px 20px;border-radius:12px;text-decoration:none;border:1px solid var(--line);color:var(--tx);transition:border-color .3s,background .3s}\n.ghost:hover,.ghost:focus-visible{border-color:var(--cyan);background:rgba(98,227,255,.06)}\n\n.visual{position:relative;display:grid;place-items:center;animation:fadeup 1s var(--ease) .45s both}\n.ring{position:absolute;width:118%;max-width:520px;aspect-ratio:1;z-index:-1;opacity:.75}\n.ring .spin{transform-origin:50% 50%;animation:spin 60s linear infinite}\n.ring .spin2{transform-origin:50% 50%;animation:spin 40s linear infinite reverse}\n@keyframes spin{to{transform:rotate(360deg)}}\n.term{\n  width:100%;max-width:420px;background:rgba(10,13,19,.88);border:1px solid #2a3342;border-radius:16px;\n  box-shadow:0 30px 80px -20px rgba(0,0,0,.8), 0 0 0 1px rgba(200,255,61,.06) inset;\n  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);overflow:hidden;\n  transition:transform .5s var(--ease), border-color .4s;\n}\n.term:hover{transform:translateY(-4px) rotate(-.4deg);border-color:rgba(200,255,61,.45)}\n.term-bar{display:flex;align-items:center;gap:7px;padding:11px 14px;border-bottom:1px solid #222a37;font-family:var(--mono);font-size:.72rem;color:var(--mu)}\n.term-bar i{width:10px;height:10px;border-radius:50%;background:#2c3544}\n.term-bar i:first-child{background:var(--ora)}\n.term-bar span{margin-left:8px}\n.term-body{padding:16px 18px 18px;font-family:var(--mono);font-size:.84rem;line-height:1.75;min-height:226px}\n.tl{margin:0;white-space:pre-wrap;word-break:break-word}\n.tl.c{color:#7f8a9b}\n.tl.p{color:var(--lime)}\n.tl.o{color:#dfe3e8}\n.tl.o b{color:var(--cyan);font-weight:600}\n.caret{display:inline-block;width:.55em;height:1.05em;background:var(--lime);vertical-align:-.15em;margin-left:2px;animation:blink 1s steps(2) infinite}\n.term-note{margin:10px 2px 0;font-size:.76rem;color:var(--mu);text-align:center}\n.scroll-hint{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);font-family:var(--mono);font-size:.7rem;letter-spacing:.2em;color:var(--mu);display:flex;flex-direction:column;align-items:center;gap:6px}\n.scroll-hint::after{content:\"\";width:1px;height:34px;background:linear-gradient(var(--lime),transparent);animation:drip 2s var(--ease) infinite;transform-origin:top}\n@keyframes drip{0%{transform:scaleY(0)}50%{transform:scaleY(1)}100%{transform:scaleY(1);opacity:0}}\n\n/* ---------- ticker ---------- */\n.ticker{overflow:hidden;border-block:1px solid var(--line);padding:14px 0;background:rgba(13,17,24,.6)}\n.ticker-track{display:flex;white-space:nowrap;will-change:transform;font-weight:800;font-size:clamp(1.8rem,5vw,3.6rem);line-height:1.1;letter-spacing:.02em}\n.ticker-track span{padding-right:.6em;color:transparent;-webkit-text-stroke:1px rgba(236,234,227,.35)}\n.ticker-track span:nth-child(3n+2){color:var(--lime);-webkit-text-stroke:0}\n.ticker-track .dot{color:var(--ora)!important;-webkit-text-stroke:0!important}\n\n/* ---------- sections ---------- */\nsection.sec{padding:clamp(80px,12vw,140px) 0}\n.wrap{width:var(--wrap);margin:0 auto}\n.sec-head{margin-bottom:clamp(36px,6vw,64px);max-width:760px}\n.idx{font-family:var(--mono);font-size:.78rem;letter-spacing:.18em;color:var(--mu);margin:0 0 12px}\n.idx span{color:var(--lime);font-weight:700}\n.sec-head .bar{display:block;width:72px;height:3px;background:linear-gradient(90deg,var(--lime),var(--cyan));border-radius:2px;margin-bottom:22px}\nh2{margin:0 0 16px;font-size:clamp(1.8rem,4.2vw,3rem);line-height:1.25;font-weight:800}\nh2>span{display:inline-block}\n.sec-lead{color:#cfd3d8;margin:0;font-size:1.04rem}\n.js .sec-head .bar{transform:scaleX(0);transform-origin:left;transition:transform 1s var(--ease)}\n.js .sec-head.in .bar{transform:scaleX(1)}\n.js .sec-head h2>span{clip-path:inset(0 100% 0 0);transition:clip-path 1.1s var(--ease) .12s}\n.js .sec-head.in h2>span{clip-path:inset(0 0 0 0)}\n.js .sec-head .idx,.js .sec-head .sec-lead{opacity:0;transform:translateY(12px);transition:opacity .8s var(--ease),transform .8s var(--ease)}\n.js .sec-head .sec-lead{transition-delay:.3s}\n.js .sec-head.in .idx,.js .sec-head.in .sec-lead{opacity:1;transform:none}\n.js .rv{opacity:0;transform:translateY(28px);transition:opacity .9s var(--ease),transform .9s var(--ease);transition-delay:calc(var(--i,0) * 110ms)}\n.js .rv.in{opacity:1;transform:none}\n\n/* ---------- why cards ---------- */\n.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n.card{\n  position:relative;padding:30px 26px 26px;border-radius:20px;background:var(--s1);border:1px solid var(--line);overflow:hidden;\n  transition:transform .45s var(--ease), border-color .35s, box-shadow .45s var(--ease);\n}\n.card::before{content:\"\";position:absolute;inset:0;background:radial-gradient(360px circle at var(--mx,50%) var(--my,0%),rgba(200,255,61,.13),transparent 60%);opacity:0;transition:opacity .35s;pointer-events:none}\n.card:hover,.card:focus-within{transform:translateY(-6px);border-color:rgba(200,255,61,.4);box-shadow:0 24px 60px -24px rgba(200,255,61,.25)}\n.card:hover::before,.card:focus-within::before{opacity:1}\n.card .num{position:absolute;right:18px;top:8px;font-family:var(--mono);font-size:3.6rem;font-weight:700;color:transparent;-webkit-text-stroke:1px rgba(236,234,227,.12);line-height:1}\n.card svg.ic{width:56px;height:56px;margin-bottom:18px}\n.ic path,.ic rect,.ic circle,.ic line,.ic polyline{fill:none;stroke:var(--lime);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.js .card .ic .draw{stroke-dasharray:200;stroke-dashoffset:200;transition:stroke-dashoffset 1.6s var(--ease) .35s}\n.js .card.in .ic .draw{stroke-dashoffset:0}\n.card h3{margin:0 0 10px;font-size:1.3rem;line-height:1.4}\n.card p{margin:0 0 18px;color:#cdd1d7;font-size:.96rem}\n.card .more{font-size:.86rem;color:var(--lime);text-decoration:none;display:inline-flex;gap:6px;align-items:center;border-bottom:1px solid transparent;transition:border-color .3s}\n.card .more:hover,.card .more:focus-visible{border-color:var(--lime)}\n.card .more span{transition:transform .3s var(--ease)}\n.card .more:hover span,.card .more:focus-visible span{transform:translateX(4px)}\n.card small{display:block;color:var(--mu);font-size:.8rem;margin:-8px 0 16px}\n\n/* ---------- flow ---------- */\n.flow-box{background:var(--s1);border:1px solid var(--line);border-radius:24px;padding:clamp(20px,4vw,40px)}\n.flow{display:flex;align-items:center}\n.machine{position:relative;flex:1;display:flex;align-items:center;border:1px solid rgba(200,255,61,.35);border-radius:18px;padding:48px 22px 24px;background:rgba(200,255,61,.025)}\n.machine-label{position:absolute;top:12px;left:18px;font-family:var(--mono);font-size:.74rem;letter-spacing:.12em;color:var(--lime)}\n.node{flex:none;min-width:120px;padding:14px 16px;border-radius:14px;background:var(--s2);border:1px solid var(--line);text-align:center;transition:border-color .3s, transform .3s var(--ease)}\n.node:hover{transform:translateY(-3px);border-color:var(--cyan)}\n.node b{display:block;font-size:1rem}\n.node span{display:block;font-size:.78rem;color:var(--mu);line-height:1.5}\n.node.model{border-color:rgba(200,255,61,.6);box-shadow:0 0 30px -6px rgba(200,255,61,.35);position:relative}\n.node.model::before{content:\"\";position:absolute;inset:-6px;border-radius:18px;border:1px dashed rgba(200,255,61,.35);animation:spin 18s linear infinite;pointer-events:none}\n.pipe{flex:1;min-width:24px;height:2px;margin:0 6px;background:repeating-linear-gradient(90deg,var(--cyan) 0 8px,transparent 8px 16px);background-size:16px 2px;animation:flowx .7s linear infinite}\n@keyframes flowx{to{background-position:16px 0}}\n@keyframes flowy{to{background-position:0 16px}}\n.pipe.ext{flex:0 0 72px;background-image:repeating-linear-gradient(90deg,#3a4352 0 6px,transparent 6px 12px);background-size:12px 2px;animation:none;position:relative;transition:background .3s}\n.pipe.ext::after{content:\"×\";position:absolute;left:50%;top:50%;transform:translate(-50%,-55%);font-family:var(--mono);color:var(--mu);background:var(--s1);padding:0 4px;font-size:.9rem;line-height:1}\n.flow.on .pipe.ext{background-image:repeating-linear-gradient(90deg,var(--ora) 0 8px,transparent 8px 16px);background-size:16px 2px;animation:flowx .7s linear infinite}\n.flow.on .pipe.ext::after{content:\"⇄\";color:var(--ora)}\n.node.extn{border-style:dashed;opacity:.55;transition:opacity .35s, border-color .35s}\n.flow.on .node.extn{opacity:1;border-color:var(--ora);box-shadow:0 0 30px -8px rgba(255,138,76,.45)}\n.flow-ctrl{display:flex;flex-wrap:wrap;align-items:center;gap:18px;margin-top:28px;padding-top:24px;border-top:1px solid var(--line)}\n.switch{\n  font:inherit;color:var(--tx);display:inline-flex;align-items:center;gap:12px;cursor:pointer;\n  background:var(--s2);border:1px solid var(--line);border-radius:999px;padding:8px 16px 8px 8px;transition:border-color .3s;\n}\n.switch:hover{border-color:var(--ora)}\n.track{width:46px;height:26px;border-radius:999px;background:#2a3240;position:relative;transition:background .3s}\n.track::after{content:\"\";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:var(--tx);transition:transform .35s var(--ease)}\n.switch[aria-checked=\"true\"] .track{background:var(--ora)}\n.switch[aria-checked=\"true\"] .track::after{transform:translateX(20px)}\n.switch .st{font-family:var(--mono);font-size:.78rem;color:var(--mu);min-width:2.4em}\n#flowNote{margin:0;flex:1;min-width:240px;color:#d6d9de;font-size:.95rem}\n#flowNote strong{color:var(--ora)}\n\n/* ---------- use ---------- */\n.uses{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}\n.use{position:relative;display:grid;grid-template-columns:110px 1fr 1.2fr;gap:24px;align-items:start;padding:32px 12px;border-bottom:1px solid var(--line);overflow:hidden}\n.use::before{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(200,255,61,.09),transparent 70%);transform:scaleX(0);transform-origin:left;transition:transform .6s var(--ease);z-index:-1}\n.use:hover::before{transform:scaleX(1)}\n.use .tag{font-family:var(--mono);font-size:.78rem;color:var(--lime);letter-spacing:.1em;padding-top:8px}\n.use h3{margin:0;font-size:clamp(1.4rem,2.8vw,2rem);line-height:1.35;transition:transform .5s var(--ease)}\n.use:hover h3{transform:translateX(8px)}\n.use p{margin:0 0 12px;color:#cdd1d7;font-size:.96rem}\n.eg{display:inline-block;font-size:.85rem;border:1px solid var(--line);border-radius:10px;padding:6px 12px;background:var(--s1);color:#dfe3e8}\n.eg::before{content:\"例 \";color:var(--cyan);font-family:var(--mono);font-size:.76rem}\n.caveat{margin:28px 0 0;padding:16px 20px;border-left:3px solid var(--cyan);background:rgba(98,227,255,.05);border-radius:0 12px 12px 0;color:#d6d9de;font-size:.95rem}\n\n/* ---------- steps ---------- */\n.start-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:56px;align-items:start}\n.start-side{position:sticky;top:96px}\n.tally{display:flex;align-items:center;gap:16px;margin-top:28px;padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--s1)}\n.tally svg{width:64px;height:64px;flex:none;transform:rotate(-90deg)}\n.tally circle{fill:none;stroke-width:6}\n.tally .bgc{stroke:#222a36}\n.tally .fgc{stroke:var(--lime);stroke-linecap:round;stroke-dasharray:163.4;stroke-dashoffset:163.4;transition:stroke-dashoffset .6s var(--ease)}\n.tally p{margin:0;font-size:.92rem;color:var(--mu)}\n.tally strong{display:block;font-size:1.3rem;color:var(--tx);font-family:var(--mono)}\n.steps{list-style:none;margin:0;padding:0 0 0 56px;position:relative}\n.rail{position:absolute;left:19px;top:8px;bottom:8px;width:2px;background:var(--line);border-radius:2px}\n.rail i{position:absolute;inset:0;background:linear-gradient(var(--lime),var(--cyan));transform:scaleY(0);transform-origin:top;border-radius:2px}\n.step{position:relative;padding:0 0 44px}\n.step:last-child{padding-bottom:0}\n.dot{position:absolute;left:-56px;top:0;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:.9rem;background:var(--bg);border:2px solid var(--line);color:var(--mu);transition:all .5s var(--ease)}\n.step.lit .dot{border-color:var(--lime);color:#0a0c10;background:var(--lime);box-shadow:0 0 0 6px rgba(200,255,61,.12)}\n.step-card{background:var(--s1);border:1px solid var(--line);border-radius:18px;padding:22px 24px;transition:border-color .35s, transform .35s var(--ease)}\n.step-card:hover,.step-card:focus-within{border-color:rgba(200,255,61,.4);transform:translateX(4px)}\n.step h3{margin:0 0 8px;font-size:1.25rem;line-height:1.45}\n.step p{margin:0 0 12px;color:#cdd1d7;font-size:.96rem}\n.step ul{margin:0 0 16px;padding:0;list-style:none;display:grid;gap:6px}\n.step li{position:relative;padding-left:20px;font-size:.92rem;color:#dfe3e8}\n.step li::before{content:\"\";position:absolute;left:2px;top:.72em;width:8px;height:2px;background:var(--cyan)}\n.check{display:inline-flex;align-items:center;gap:10px;cursor:pointer;font-size:.88rem;color:var(--mu);user-select:none}\n.check input{appearance:none;-webkit-appearance:none;width:22px;height:22px;margin:0;border:2px solid #3a4352;border-radius:6px;display:grid;place-items:center;cursor:pointer;transition:background .25s,border-color .25s}\n.check input::after{content:\"\";width:10px;height:6px;border-left:2px solid #0a0c10;border-bottom:2px solid #0a0c10;transform:rotate(-45deg) scale(0);margin-top:-3px;transition:transform .25s var(--ease)}\n.check input:checked{background:var(--lime);border-color:var(--lime)}\n.check input:checked::after{transform:rotate(-45deg) scale(1)}\n.check input:checked+span{color:var(--lime)}\n\n/* ---------- notes ---------- */\n.notes{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n.note{position:relative;background:var(--s1);border:1px solid var(--line);border-radius:18px;padding:30px 24px 24px;overflow:hidden;transition:transform .4s var(--ease),border-color .3s}\n.note::before{content:\"\";position:absolute;inset:0 0 auto 0;height:6px;background:repeating-linear-gradient(-45deg,var(--ora) 0 10px,transparent 10px 20px);background-size:28.28px 6px;animation:stripe 1.6s linear infinite}\n@keyframes stripe{to{background-position:28.28px 0}}\n.note:hover{transform:translateY(-4px);border-color:rgba(255,138,76,.5)}\n.note .lbl{font-family:var(--mono);font-size:.74rem;letter-spacing:.14em;color:var(--ora)}\n.note h3{margin:6px 0 10px;font-size:1.15rem;line-height:1.45}\n.note p{margin:0;color:#cdd1d7;font-size:.94rem}\n.about{margin-top:28px;font-size:.88rem;color:var(--mu);border:1px dashed var(--line);border-radius:14px;padding:14px 18px}\n\n/* ---------- final ---------- */\n.final{text-align:center;padding:clamp(80px,12vw,130px) 0;position:relative;overflow:hidden}\n.final::before{content:\"\";position:absolute;left:50%;top:50%;width:min(720px,120vw);aspect-ratio:1;transform:translate(-50%,-50%);background:radial-gradient(circle,rgba(200,255,61,.12),transparent 60%);z-index:-1;animation:breathe 6s ease-in-out infinite}\n@keyframes breathe{50%{transform:translate(-50%,-50%) scale(1.12)}}\n.final h2{font-size:clamp(2rem,5vw,3.6rem)}\n.final p{color:#cfd3d8;margin:0 auto 30px;max-width:34em}\nfooter{border-top:1px solid var(--line);padding:30px 0 40px;color:var(--mu);font-size:.84rem}\nfooter .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px}\nfooter a{color:var(--tx)}\n\n/* ---------- responsive ---------- */\n@media (max-width:1060px){\n  .nav a{padding:6px 7px;font-size:.84rem}\n}\n@media (max-width:900px){\n  .hero-grid{grid-template-columns:1fr;gap:36px}\n  .visual{max-width:440px;width:100%;margin:0 auto}\n  .cards,.notes{grid-template-columns:1fr}\n  .start-grid{grid-template-columns:1fr;gap:28px}\n  .start-side{position:static}\n  .use{grid-template-columns:1fr;gap:8px;padding:26px 6px}\n  .use .tag{padding-top:0}\n}\n@media (max-width:820px){\n  .nav a{display:none}\n  .mini-cta{display:inline-flex;font-size:.8rem;text-decoration:none;color:#0a0c10;background:var(--lime);border-radius:999px;padding:6px 12px;font-weight:700}\n  .flow{flex-direction:column;align-items:stretch}\n  .machine{flex-direction:column;align-items:stretch;padding:44px 18px 18px}\n  .pipe{flex:none;width:2px;height:30px;min-width:0;margin:6px auto;background:repeating-linear-gradient(180deg,var(--cyan) 0 8px,transparent 8px 16px);background-size:2px 16px;animation-name:flowy}\n  .pipe.ext{flex:none;height:44px;background-image:repeating-linear-gradient(180deg,#3a4352 0 6px,transparent 6px 12px);background-size:2px 12px}\n  .flow.on .pipe.ext{background-image:repeating-linear-gradient(180deg,var(--ora) 0 8px,transparent 8px 16px);background-size:2px 16px;animation-name:flowy}\n  .node{min-width:0}\n}\n@media (max-width:520px){\n  :root{--wrap:calc(100% - 36px)}\n  .bar-top{padding:0 18px}\n  .brand small{display:none}\n  .motion-btn .lbl{display:none}\n  .motion-btn{padding:8px 10px}\n  .hero{padding-top:86px;align-items:flex-start}\n  .term-body{font-size:.78rem;min-height:210px}\n  .scroll-hint{display:none}\n  .pillars li{font-size:.84rem;padding:7px 12px}\n  .cta{width:100%;justify-content:center}\n  .ghost{width:100%;justify-content:center}\n  .steps{padding-left:48px}\n  .dot{left:-48px;width:34px;height:34px;font-size:.82rem}\n  .rail{left:16px}\n}\n\n/* ---------- motion off ---------- */\nhtml.still *,html.still *::before,html.still *::after{animation:none!important;transition:none!important}\nhtml.still .rv,html.still .sec-head .idx,html.still .sec-head .sec-lead{opacity:1!important;transform:none!important}\nhtml.still .sec-head .bar{transform:none!important}\nhtml.still .sec-head h2>span{clip-path:none!important}\nhtml.still .card .ic .draw{stroke-dashoffset:0!important}\nhtml.still .ticker-track{transform:none!important}\nhtml.still .grad{background-position:0 0}\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  *,*::before,*::after{animation:none!important;transition:none!important}\n  .js .rv,.js .sec-head .idx,.js .sec-head .sec-lead{opacity:1;transform:none}\n  .js .sec-head .bar{transform:none}\n  .js .sec-head h2>span{clip-path:none}\n  .js .card .ic .draw{stroke-dashoffset:0}\n}\n\u003c/style>\n\u003c/head>\n\u003cbody>\n\u003ca class=\"skip\" href=\"#main\">本文へスキップ\u003c/a>\n\u003cdiv class=\"progress\" id=\"progress\" aria-hidden=\"true\">\u003c/div>\n\n\u003cheader class=\"bar-top\" id=\"top-bar\">\n  \u003ca class=\"brand\" href=\"#top\" aria-label=\"ページ先頭へ\">\n    \u003cspan class=\"brand-mark\" aria-hidden=\"true\">\u003c/span>\n    \u003cspan>ローカルLLM \u003csmall>ON-DEVICE AI\u003c/small>\u003c/span>\n  \u003c/a>\n  \u003cnav class=\"nav\" aria-label=\"ページ内ナビゲーション\">\n    \u003ca href=\"#why\">魅力\u003c/a>\n    \u003ca href=\"#flow\">データの流れ\u003c/a>\n    \u003ca href=\"#use\">用途\u003c/a>\n    \u003ca href=\"#start\">導入手順\u003c/a>\n    \u003ca href=\"#notes\">注意点\u003c/a>\n  \u003c/nav>\n  \u003cdiv style=\"display:flex;gap:8px;align-items:center\">\n    \u003ca class=\"mini-cta\" href=\"#start\">導入手順\u003c/a>\n    \u003cbutton class=\"motion-btn\" id=\"motionBtn\" type=\"button\" aria-pressed=\"false\">\n      \u003cspan class=\"ico\" aria-hidden=\"true\">\u003c/span>\u003cspan class=\"lbl\">動きを止める\u003c/span>\u003cspan class=\"sr\" id=\"motionSr\">アニメーションを止める\u003c/span>\n    \u003c/button>\n  \u003c/div>\n\u003c/header>\n\n\u003cmain id=\"main\">\n\u003c!-- HERO -->\n\u003csection class=\"hero\" id=\"top\" aria-labelledby=\"hero-title\">\n  \u003ccanvas id=\"field\" aria-hidden=\"true\">\u003c/canvas>\n  \u003cdiv class=\"hero-grid\" id=\"heroGrid\">\n    \u003cdiv>\n      \u003cp class=\"eyebrow\">LOCAL LLM / 自分の机の上で動くAI\u003c/p>\n      \u003ch1 id=\"hero-title\">\n        \u003cspan class=\"ln\">\u003cspan>AIを、\u003c/span>\u003c/span>\n        \u003cspan class=\"ln\">\u003cspan class=\"grad\">手元で動かす。\u003c/span>\u003c/span>\n      \u003c/h1>\n      \u003cp class=\"lead\">いつも使っている生成AIを、自分のPCや手元の計算機で。ローカルLLMは、モデルを選び、試し方を決め、データの扱いまで自分で設計できる——そんな「もうひとつの使い方」です。\u003c/p>\n      \u003cul class=\"pillars\" aria-label=\"ローカルLLMの魅力\">\n        \u003cli>\u003cb>01\u003c/b>手元で試す楽しさ\u003c/li>\n        \u003cli>\u003cb>02\u003c/b>モデルを選ぶ自由\u003c/li>\n        \u003cli>\u003cb>03\u003c/b>データの扱いを設計\u003c/li>\n      \u003c/ul>\n      \u003cdiv class=\"cta-row\">\n        \u003ca class=\"cta\" href=\"#start\">導入の4ステップを見る \u003cspan class=\"arr\" aria-hidden=\"true\">↓\u003c/span>\u003c/a>\n        \u003ca class=\"ghost\" href=\"#why\">まず魅力を知る\u003c/a>\n      \u003c/div>\n    \u003c/div>\n\n    \u003cdiv class=\"visual\">\n      \u003csvg class=\"ring\" viewBox=\"0 0 400 400\" aria-hidden=\"true\">\n        \u003cg class=\"spin\">\n          \u003ccircle cx=\"200\" cy=\"200\" r=\"190\" fill=\"none\" stroke=\"rgba(200,255,61,.35)\" stroke-width=\"1\" stroke-dasharray=\"2 10\"/>\n          \u003ctext font-family=\"ui-monospace,Consolas,monospace\" font-size=\"11\" fill=\"rgba(200,255,61,.6)\" letter-spacing=\"4\">\n            \u003ctextPath href=\"#ringPath\">YOUR MACHINE · YOUR MODEL · YOUR DATA FLOW · \u003c/textPath>\n          \u003c/text>\n        \u003c/g>\n        \u003cg class=\"spin2\">\n          \u003ccircle cx=\"200\" cy=\"200\" r=\"160\" fill=\"none\" stroke=\"rgba(98,227,255,.25)\" stroke-width=\"1\" stroke-dasharray=\"40 14 4 14\"/>\n        \u003c/g>\n        \u003cpath id=\"ringPath\" d=\"M200,200 m-176,0 a176,176 0 1,1 352,0 a176,176 0 1,1 -352,0\" fill=\"none\"/>\n      \u003c/svg>\n      \u003cdiv style=\"width:100%;max-width:420px\">\n        \u003cdiv class=\"term\" role=\"group\" aria-label=\"ローカル実行の利用イメージ\">\n          \u003cdiv class=\"term-bar\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003cspan>local-session — 利用イメージ\u003c/span>\u003c/div>\n          \u003cdiv class=\"term-body\" id=\"termBody\">\n            \u003cp class=\"tl c\"># 実行場所：このPC（手元の計算機）\u003c/p>\n            \u003cp class=\"tl c\"># モデル：用途に合わせて自分で選んだもの\u003c/p>\n            \u003cp class=\"tl p\">› この議事メモを、決定事項と宿題に分けて\u003c/p>\n            \u003cp class=\"tl o\">\u003cb>決定事項\u003c/b>：次回までに案を2つに絞る\u003c/p>\n            \u003cp class=\"tl o\">\u003cb>宿題\u003c/b>：必要な資料をそろえる\u003c/p>\n            \u003cp class=\"tl p\">› 次は文体をやわらかくして\u003c/p>\n          \u003c/div>\n        \u003c/div>\n        \u003cp class=\"term-note\">※ 画面はイメージです。速度や出力はモデル・機器・設定によって変わります。\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/div>\n  \u003cdiv class=\"scroll-hint\" aria-hidden=\"true\">SCROLL\u003c/div>\n\u003c/section>\n\n\u003cdiv class=\"ticker\" aria-hidden=\"true\">\n  \u003cdiv class=\"ticker-track\" data-dir=\"-1\">\n    \u003cspan>ON-DEVICE\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>試す\u003c/span>\u003cspan>LOCAL LLM\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>選ぶ\u003c/span>\u003cspan>YOUR MACHINE\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>設計する\u003c/span>\u003cspan>ON-DEVICE\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>試す\u003c/span>\u003cspan>LOCAL LLM\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>選ぶ\u003c/span>\n  \u003c/div>\n\u003c/div>\n\n\u003c!-- WHY -->\n\u003csection class=\"sec\" id=\"why\" aria-labelledby=\"why-title\">\n  \u003cdiv class=\"wrap\">\n    \u003cdiv class=\"sec-head\">\n      \u003cp class=\"idx\">\u003cspan>01\u003c/span> / WHY LOCAL\u003c/p>\n      \u003cspan class=\"bar\" aria-hidden=\"true\">\u003c/span>\n      \u003ch2 id=\"why-title\">\u003cspan>手元で動かす、3つの魅力。\u003c/span>\u003c/h2>\n      \u003cp class=\"sec-lead\">クラウドのAIサービスと比べて「どちらが上」という話ではありません。自分の手で動かすからこそ得られる体験があります。\u003c/p>\n    \u003c/div>\n    \u003cdiv class=\"cards\">\n      \u003carticle class=\"card rv\" style=\"--i:0\">\n        \u003cspan class=\"num\" aria-hidden=\"true\">01\u003c/span>\n        \u003csvg class=\"ic\" viewBox=\"0 0 56 56\" aria-hidden=\"true\">\n          \u003crect class=\"draw\" x=\"6\" y=\"10\" width=\"44\" height=\"30\" rx=\"4\"/>\n          \u003cline class=\"draw\" x1=\"20\" y1=\"48\" x2=\"36\" y2=\"48\"/>\n          \u003cpolyline class=\"draw\" points=\"14,20 20,25 14,30\"/>\n          \u003cline class=\"draw\" x1=\"24\" y1=\"31\" x2=\"34\" y2=\"31\"/>\n        \u003c/svg>\n        \u003ch3>手元で試す楽しさ\u003c/h3>\n        \u003cp>思いついたら、自分の環境ですぐ実験。プロンプトや設定を少し変えて、返ってくる答えの違いを観察する——仕組みに触れながら遊べる面白さがあります。\u003c/p>\n        \u003ca class=\"more\" href=\"#start\">試し方を見る \u003cspan aria-hidden=\"true\">→\u003c/span>\u003c/a>\n      \u003c/article>\n      \u003carticle class=\"card rv\" style=\"--i:1\">\n        \u003cspan class=\"num\" aria-hidden=\"true\">02\u003c/span>\n        \u003csvg class=\"ic\" viewBox=\"0 0 56 56\" aria-hidden=\"true\">\n          \u003crect class=\"draw\" x=\"6\" y=\"6\" width=\"18\" height=\"18\" rx=\"3\"/>\n          \u003crect class=\"draw\" x=\"32\" y=\"6\" width=\"18\" height=\"18\" rx=\"3\"/>\n          \u003crect class=\"draw\" x=\"6\" y=\"32\" width=\"18\" height=\"18\" rx=\"3\"/>\n          \u003ccircle class=\"draw\" cx=\"41\" cy=\"41\" r=\"9\"/>\n        \u003c/svg>\n        \u003ch3>モデルを選ぶ自由\u003c/h3>\n        \u003cp>大きさ、得意な分野、利用条件。性格の違うモデルの中から、用途と機器に合うものを選び、入れ替えて比べられます。正解はひとつではありません。\u003c/p>\n        \u003ca class=\"more\" href=\"#step3\">選び方のポイント \u003cspan aria-hidden=\"true\">→\u003c/span>\u003c/a>\n      \u003c/article>\n      \u003carticle class=\"card rv\" style=\"--i:2\">\n        \u003cspan class=\"num\" aria-hidden=\"true\">03\u003c/span>\n        \u003csvg class=\"ic\" viewBox=\"0 0 56 56\" aria-hidden=\"true\">\n          \u003cpath class=\"draw\" d=\"M28 6 L46 13 V27 C46 39 38 46 28 50 C18 46 10 39 10 27 V13 Z\"/>\n          \u003cpolyline class=\"draw\" points=\"20,28 26,34 37,22\"/>\n        \u003c/svg>\n        \u003ch3>データの扱いを設計できる\u003c/h3>\n        \u003cp>どのファイルを読ませるか、何を外部とつなぐか。データがどこを通るかを、自分で決めて組み立てられます。\u003c/p>\n        \u003csmall>※ ローカル実行だけで完全な秘密保持が自動的に保証されるわけではありません。\u003c/small>\n        \u003ca class=\"more\" href=\"#flow\">データの流れを見る \u003cspan aria-hidden=\"true\">→\u003c/span>\u003c/a>\n      \u003c/article>\n    \u003c/div>\n  \u003c/div>\n\u003c/section>\n\n\u003c!-- FLOW -->\n\u003csection class=\"sec\" id=\"flow\" aria-labelledby=\"flow-title\" style=\"padding-top:0\">\n  \u003cdiv class=\"wrap\">\n    \u003cdiv class=\"sec-head\">\n      \u003cp class=\"idx\">\u003cspan>02\u003c/span> / DATA FLOW\u003c/p>\n      \u003cspan class=\"bar\" aria-hidden=\"true\">\u003c/span>\n      \u003ch2 id=\"flow-title\">\u003cspan>データの通り道を、自分で決める。\u003c/span>\u003c/h2>\n      \u003cp class=\"sec-lead\">ローカルLLMでは、入力からモデル、出力までを手元の機器で処理できます。ただし外部連携や設定しだいで通信は発生します。スイッチで違いを確かめてください。\u003c/p>\n    \u003c/div>\n    \u003cdiv class=\"flow-box rv\">\n      \u003cdiv class=\"flow\" id=\"flowDiagram\">\n        \u003cdiv class=\"machine\">\n          \u003cspan class=\"machine-label\">YOUR PC / 手元の計算機\u003c/span>\n          \u003cdiv class=\"node\">\u003cb>入力・資料\u003c/b>\u003cspan>質問、メモ、コード\u003c/span>\u003c/div>\n          \u003cdiv class=\"pipe\" aria-hidden=\"true\">\u003c/div>\n          \u003cdiv class=\"node model\">\u003cb>モデル\u003c/b>\u003cspan>自分で選んで実行\u003c/span>\u003c/div>\n          \u003cdiv class=\"pipe\" aria-hidden=\"true\">\u003c/div>\n          \u003cdiv class=\"node\">\u003cb>出力\u003c/b>\u003cspan>下書き、整理結果\u003c/span>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"pipe ext\" aria-hidden=\"true\">\u003c/div>\n        \u003cdiv class=\"node extn\">\u003cb>外部サービス\u003c/b>\u003cspan>検索・拡張機能・同期など\u003c/span>\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"flow-ctrl\">\n        \u003cbutton class=\"switch\" id=\"extSwitch\" type=\"button\" role=\"switch\" aria-checked=\"false\">\n          \u003cspan class=\"track\" aria-hidden=\"true\">\u003c/span>\u003cspan>外部連携\u003c/span>\u003cspan class=\"st\" id=\"extState\">OFF\u003c/span>\n        \u003c/button>\n        \u003cp id=\"flowNote\" aria-live=\"polite\">外部連携を使わない構成なら、入力・モデル・出力の流れを\u003cstrong style=\"color:var(--lime)\">この機器の中にとどめるよう設計\u003c/strong>できます。\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/div>\n\u003c/section>\n\n\u003c!-- USE -->\n\u003csection class=\"sec\" id=\"use\" aria-labelledby=\"use-title\" style=\"padding-top:0\">\n  \u003cdiv class=\"wrap\">\n    \u003cdiv class=\"sec-head\">\n      \u003cp class=\"idx\">\u003cspan>03\u003c/span> / USE CASES\u003c/p>\n      \u003cspan class=\"bar\" aria-hidden=\"true\">\u003c/span>\n      \u003ch2 id=\"use-title\">\u003cspan>たとえば、こんな使い方。\u003c/span>\u003c/h2>\n      \u003cp class=\"sec-lead\">毎日の作業の「最初のたたき台」に。手元で動かすからこそ、気軽に何度でも試せます。\u003c/p>\n    \u003c/div>\n    \u003cul class=\"uses\">\n      \u003cli class=\"use rv\" style=\"--i:0\">\n        \u003cspan class=\"tag\">USE 01\u003c/span>\n        \u003ch3>文章の下書き\u003c/h3>\n        \u003cdiv>\n          \u003cp>メール、企画メモ、ブログの構成案など。ゼロから書く前の「たたき台」を作り、自分の言葉で仕上げていきます。\u003c/p>\n          \u003cspan class=\"eg\">この箇条書きを、ていねいなお知らせ文にして\u003c/span>\n        \u003c/div>\n      \u003c/li>\n      \u003cli class=\"use rv\" style=\"--i:1\">\n        \u003cspan class=\"tag\">USE 02\u003c/span>\n        \u003ch3>コードの相談\u003c/h3>\n        \u003cdiv>\n          \u003cp>エラーの読み解き、関数の説明、書き方の別案。手元のコードを見せながら、壁打ち相手として使えます。\u003c/p>\n          \u003cspan class=\"eg\">この関数が何をしているか、順番に説明して\u003c/span>\n        \u003c/div>\n      \u003c/li>\n      \u003cli class=\"use rv\" style=\"--i:2\">\n        \u003cspan class=\"tag\">USE 03\u003c/span>\n        \u003ch3>手元資料の整理\u003c/h3>\n        \u003cdiv>\n          \u003cp>議事メモや読書ノートを要点に分けたり、見出しをつけたり。散らかった情報に、最初の秩序を与えます。\u003c/p>\n          \u003cspan class=\"eg\">このメモを、決定事項と宿題に分けて\u003c/span>\n        \u003c/div>\n      \u003c/li>\n    \u003c/ul>\n    \u003cp class=\"caveat rv\">うまくいくかどうか、どれくらい正確かは\u003cstrong>用途とモデルに依存\u003c/strong>します。出力はそのまま使わず、内容を確認してから活用しましょう。\u003c/p>\n  \u003c/div>\n\u003c/section>\n\n\u003cdiv class=\"ticker\" aria-hidden=\"true\">\n  \u003cdiv class=\"ticker-track\" data-dir=\"1\">\n    \u003cspan>START SMALL\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>決める\u003c/span>\u003cspan>CHECK MEMORY\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>読む\u003c/span>\u003cspan>TRY IT\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>試す\u003c/span>\u003cspan>START SMALL\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>決める\u003c/span>\u003cspan>CHECK MEMORY\u003c/span>\u003cspan class=\"dot\">✦\u003c/span>\u003cspan>読む\u003c/span>\n  \u003c/div>\n\u003c/div>\n\n\u003c!-- START -->\n\u003csection class=\"sec\" id=\"start\" aria-labelledby=\"start-title\">\n  \u003cdiv class=\"wrap start-grid\">\n    \u003cdiv class=\"start-side\">\n      \u003cdiv class=\"sec-head\" style=\"margin-bottom:0\">\n        \u003cp class=\"idx\">\u003cspan>04\u003c/span> / GET STARTED\u003c/p>\n        \u003cspan class=\"bar\" aria-hidden=\"true\">\u003c/span>\n        \u003ch2 id=\"start-title\">\u003cspan>導入は、4つのステップで。\u003c/span>\u003c/h2>\n        \u003cp class=\"sec-lead\">いきなり大きく始める必要はありません。順番に確認して、小さく動かすところから。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"tally rv\">\n        \u003csvg viewBox=\"0 0 64 64\" aria-hidden=\"true\">\u003ccircle class=\"bgc\" cx=\"32\" cy=\"32\" r=\"26\"/>\u003ccircle class=\"fgc\" id=\"tallyRing\" cx=\"32\" cy=\"32\" r=\"26\"/>\u003c/svg>\n        \u003cp aria-live=\"polite\">\u003cstrong>\u003cspan id=\"tallyNum\">0\u003c/span> / 4\u003c/strong>自分用チェック（この画面の中だけで使えます）\u003c/p>\n      \u003c/div>\n    \u003c/div>\n\n    \u003col class=\"steps\" id=\"steps\">\n      \u003cspan class=\"rail\" aria-hidden=\"true\">\u003ci id=\"railFill\">\u003c/i>\u003c/span>\n      \u003cli class=\"step rv\" id=\"step1\">\n        \u003cspan class=\"dot\" aria-hidden=\"true\">1\u003c/span>\n        \u003cdiv class=\"step-card\">\n          \u003ch3>\u003cspan class=\"sr\">ステップ1：\u003c/span>用途を決める\u003c/h3>\n          \u003cp>何に使いたいかで、向いているモデルや必要な機器が変わります。まずは目的をひとつに絞りましょう。\u003c/p>\n          \u003cul>\n            \u003cli>文章の下書き？ コードの相談？ 資料の整理？\u003c/li>\n            \u003cli>日本語でのやりとりが中心か\u003c/li>\n            \u003cli>どんなデータを扱うか（個人情報・社外秘を含むか）\u003c/li>\n          \u003c/ul>\n          \u003clabel class=\"check\">\u003cinput type=\"checkbox\" class=\"chk\">\u003cspan>用途を決めた\u003c/span>\u003c/label>\n        \u003c/div>\n      \u003c/li>\n      \u003cli class=\"step rv\" id=\"step2\">\n        \u003cspan class=\"dot\" aria-hidden=\"true\">2\u003c/span>\n        \u003cdiv class=\"step-card\">\n          \u003ch3>\u003cspan class=\"sr\">ステップ2：\u003c/span>機器と必要メモリを確認する\u003c/h3>\n          \u003cp>ローカルLLMは手元の機器の力で動きます。モデルごとに必要なメモリ量が異なるため、先に自分の環境を把握しておきます。\u003c/p>\n          \u003cul>\n            \u003cli>PCのメモリ（RAM）と、あればGPUのメモリ\u003c/li>\n            \u003cli>モデルを置くためのストレージの空き容量\u003c/li>\n            \u003cli>必要量の目安は、モデル配布元の情報で確認する\u003c/li>\n          \u003c/ul>\n          \u003clabel class=\"check\">\u003cinput type=\"checkbox\" class=\"chk\">\u003cspan>手元の環境を確認した\u003c/span>\u003c/label>\n        \u003c/div>\n      \u003c/li>\n      \u003cli class=\"step rv\" id=\"step3\">\n        \u003cspan class=\"dot\" aria-hidden=\"true\">3\u003c/span>\n        \u003cdiv class=\"step-card\">\n          \u003ch3>\u003cspan class=\"sr\">ステップ3：\u003c/span>利用条件を読んでモデルを選ぶ\u003c/h3>\n          \u003cp>モデルにはそれぞれライセンスや利用条件があります。すべてが無料・商用利用可能とは限りません。\u003c/p>\n          \u003cul>\n            \u003cli>個人利用・商用利用それぞれの可否\u003c/li>\n            \u003cli>再配布や改変に関する条件\u003c/li>\n            \u003cli>用途（ステップ1）と機器（ステップ2）に合う大きさか\u003c/li>\n          \u003c/ul>\n          \u003clabel class=\"check\">\u003cinput type=\"checkbox\" class=\"chk\">\u003cspan>利用条件を読んで選んだ\u003c/span>\u003c/label>\n        \u003c/div>\n      \u003c/li>\n      \u003cli class=\"step rv\" id=\"step4\">\n        \u003cspan class=\"dot\" aria-hidden=\"true\">4\u003c/span>\n        \u003cdiv class=\"step-card\">\n          \u003ch3>\u003cspan class=\"sr\">ステップ4：\u003c/span>小さく試す\u003c/h3>\n          \u003cp>小さめのモデル、短い入力、重要ではないデータから。自分の用途で速度や出力の質感を確かめ、少しずつ広げていきます。\u003c/p>\n          \u003cul>\n            \u003cli>まずは短い質問や要約で動作を確認\u003c/li>\n            \u003cli>外部連携の設定がどうなっているかも確認\u003c/li>\n            \u003cli>物足りなければ、モデルや設定を入れ替えて比べる\u003c/li>\n          \u003c/ul>\n          \u003clabel class=\"check\">\u003cinput type=\"checkbox\" class=\"chk\">\u003cspan>小さく試してみた\u003c/span>\u003c/label>\n        \u003c/div>\n      \u003c/li>\n    \u003c/ol>\n  \u003c/div>\n\u003c/section>\n\n\u003c!-- NOTES -->\n\u003csection class=\"sec\" id=\"notes\" aria-labelledby=\"notes-title\" style=\"padding-top:0\">\n  \u003cdiv class=\"wrap\">\n    \u003cdiv class=\"sec-head\">\n      \u003cp class=\"idx\">\u003cspan>05\u003c/span> / BEFORE YOU START\u003c/p>\n      \u003cspan class=\"bar\" aria-hidden=\"true\">\u003c/span>\n      \u003ch2 id=\"notes-title\">\u003cspan>始める前に、知っておきたいこと。\u003c/span>\u003c/h2>\n      \u003cp class=\"sec-lead\">かっこよさの裏側にある、正直なポイントです。\u003c/p>\n    \u003c/div>\n    \u003cdiv class=\"notes\">\n      \u003carticle class=\"note rv\" style=\"--i:0\">\n        \u003cspan class=\"lbl\">NOTE 01\u003c/span>\n        \u003ch3>速度と必要メモリは「条件しだい」\u003c/h3>\n        \u003cp>応答の速さや必要なメモリは、モデル・機器・設定によって大きく変わります。同じモデルでも環境が違えば体感は別物です。\u003c/p>\n      \u003c/article>\n      \u003carticle class=\"note rv\" style=\"--i:1\">\n        \u003cspan class=\"lbl\">NOTE 02\u003c/span>\n        \u003ch3>無料・商用可とは限らない\u003c/h3>\n        \u003cp>モデルごとに利用条件が定められています。特に仕事で使う場合は、商用利用の可否や条件を必ず確認してください。\u003c/p>\n      \u003c/article>\n      \u003carticle class=\"note rv\" style=\"--i:2\">\n        \u003cspan class=\"lbl\">NOTE 03\u003c/span>\n        \u003ch3>ローカル＝自動的に秘密保持、ではない\u003c/h3>\n        \u003cp>外部連携や設定によっては通信が発生します。どこに何が送られうるかを確認し、データの扱いを自分で設計することが大切です。\u003c/p>\n      \u003c/article>\n    \u003c/div>\n    \u003cp class=\"about rv\">このページは特定の製品・サービスの販売を目的としたものではありません。性能の数値、順位、導入実績などは掲載していません。\u003c/p>\n  \u003c/div>\n\u003c/section>\n\n\u003csection class=\"final\" aria-labelledby=\"final-title\">\n  \u003cdiv class=\"wrap\">\n    \u003cdiv class=\"sec-head\" style=\"margin:0 auto 20px\">\n      \u003cp class=\"idx\">\u003cspan>→\u003c/span> / NEXT\u003c/p>\n      \u003cspan class=\"bar\" aria-hidden=\"true\" style=\"margin-inline:auto\">\u003c/span>\n      \u003ch2 id=\"final-title\">\u003cspan>最初の一歩は、小さく。\u003c/span>\u003c/h2>\n    \u003c/div>\n    \u003cp class=\"rv\">用途をひとつ決めて、手元の環境を確かめるところから。あなたの机の上で、AIが動き出します。\u003c/p>\n    \u003ca class=\"cta rv\" href=\"#start\">導入の4ステップに戻る \u003cspan class=\"arr\" aria-hidden=\"true\">↑\u003c/span>\u003c/a>\n  \u003c/div>\n\u003c/section>\n\u003c/main>\n\n\u003cfooter>\n  \u003cdiv class=\"wrap\">\n    \u003cspan>ローカルLLM — 手元で動かすという選択肢の紹介ページ\u003c/span>\n    \u003ca href=\"#top\">ページ先頭へ ↑\u003c/a>\n  \u003c/div>\n\u003c/footer>\n\n\u003cscript>\n(function(){\n  var root = document.documentElement;\n  var mq = window.matchMedia ? matchMedia('(prefers-reduced-motion: reduce)') : {matches:false};\n  var still = mq.matches;\n  var btn = document.getElementById('motionBtn');\n  var btnLbl = btn.querySelector('.lbl');\n  var btnSr = document.getElementById('motionSr');\n\n  /* ---------- reveal ---------- */\n  var revealEls = document.querySelectorAll('.rv, .sec-head');\n  if ('IntersectionObserver' in window) {\n    var io = new IntersectionObserver(function(entries){\n      entries.forEach(function(e){\n        if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }\n      });\n    }, {threshold:.15, rootMargin:'0px 0px -6% 0px'});\n    revealEls.forEach(function(el){ io.observe(el); });\n  } else {\n    revealEls.forEach(function(el){ el.classList.add('in'); });\n  }\n\n  /* ---------- canvas field ---------- */\n  var cv = document.getElementById('field');\n  var ctx = cv.getContext('2d');\n  var W = 0, H = 0, nodes = [], pulses = [], raf = 0, heroVisible = true, lastSpawn = 0;\n  var ptr = {x:-9999, y:-9999};\n  var LINK = 140;\n\n  function size(){\n    var dpr = Math.min(2, window.devicePixelRatio || 1);\n    W = cv.clientWidth; H = cv.clientHeight;\n    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);\n    ctx.setTransform(dpr,0,0,dpr,0,0);\n    var n = Math.min(95, Math.max(32, Math.round(W * H / 15000)));\n    nodes = [];\n    for (var i = 0; i \u003c n; i++) {\n      nodes.push({\n        x: Math.random() * W, y: Math.random() * H,\n        vx: (Math.random() - .5) * .35, vy: (Math.random() - .5) * .35,\n        r: Math.random() * 1.6 + .8, hot: Math.random() \u003c .12\n      });\n    }\n    pulses = [];\n  }\n\n  function spawnPulse(){\n    var a = nodes[(Math.random() * nodes.length) | 0], best = null, bd = LINK;\n    for (var i = 0; i \u003c nodes.length; i++) {\n      var b = nodes[i]; if (b === a) continue;\n      var d = Math.hypot(a.x - b.x, a.y - b.y);\n      if (d \u003c bd) { bd = d; best = b; }\n    }\n    if (best) pulses.push({a:a, b:best, t:0});\n  }\n\n  function draw(move){\n    ctx.clearRect(0,0,W,H);\n    var i, j, a, b, d;\n    if (move) {\n      for (i = 0; i \u003c nodes.length; i++) {\n        a = nodes[i];\n        var dx = a.x - ptr.x, dy = a.y - ptr.y, dd = Math.hypot(dx, dy);\n        if (dd \u003c 130 && dd > 0) { a.x += dx / dd * .9; a.y += dy / dd * .9; }\n        a.x += a.vx; a.y += a.vy;\n        if (a.x \u003c -20) a.x = W + 20; else if (a.x > W + 20) a.x = -20;\n        if (a.y \u003c -20) a.y = H + 20; else if (a.y > H + 20) a.y = -20;\n      }\n    }\n    ctx.lineWidth = 1;\n    for (i = 0; i \u003c nodes.length; i++) {\n      a = nodes[i];\n      for (j = i + 1; j \u003c nodes.length; j++) {\n        b = nodes[j];\n        d = Math.hypot(a.x - b.x, a.y - b.y);\n        if (d \u003c LINK) {\n          ctx.strokeStyle = 'rgba(140,165,200,' + ((1 - d / LINK) * .28).toFixed(3) + ')';\n          ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();\n        }\n      }\n    }\n    for (i = 0; i \u003c nodes.length; i++) {\n      a = nodes[i];\n      ctx.fillStyle = a.hot ? 'rgba(200,255,61,.9)' : 'rgba(200,210,225,.55)';\n      ctx.beginPath(); ctx.arc(a.x, a.y, a.hot ? a.r + .8 : a.r, 0, 6.283); ctx.fill();\n    }\n    for (i = pulses.length - 1; i >= 0; i--) {\n      var p = pulses[i];\n      if (move) p.t += .018;\n      if (p.t >= 1) { pulses.splice(i, 1); continue; }\n      var x = p.a.x + (p.b.x - p.a.x) * p.t, y = p.a.y + (p.b.y - p.a.y) * p.t;\n      ctx.fillStyle = 'rgba(200,255,61,.18)';\n      ctx.beginPath(); ctx.arc(x, y, 7, 0, 6.283); ctx.fill();\n      ctx.fillStyle = 'rgba(220,255,150,.95)';\n      ctx.beginPath(); ctx.arc(x, y, 2.2, 0, 6.283); ctx.fill();\n    }\n  }\n\n  function loop(ts){\n    raf = 0;\n    if (still || !heroVisible) return;\n    if (ts - lastSpawn > 260) { spawnPulse(); lastSpawn = ts; }\n    draw(true);\n    raf = requestAnimationFrame(loop);\n  }\n  function startLoop(){ if (!raf && !still && heroVisible) raf = requestAnimationFrame(loop); }\n  function drawStatic(){\n    pulses = [];\n    for (var k = 0; k \u003c 6; k++) { spawnPulse(); }\n    pulses.forEach(function(p, idx){ p.t = .2 + idx * .1; });\n    draw(false);\n  }\n\n  size();\n  var hero = document.getElementById('top');\n  hero.addEventListener('pointermove', function(e){\n    var r = cv.getBoundingClientRect(); ptr.x = e.clientX - r.left; ptr.y = e.clientY - r.top;\n  });\n  hero.addEventListener('pointerleave', function(){ ptr.x = ptr.y = -9999; });\n  if ('IntersectionObserver' in window) {\n    new IntersectionObserver(function(en){\n      heroVisible = en[0].isIntersecting;\n      if (heroVisible) startLoop();\n    }).observe(hero);\n  }\n  var rt;\n  window.addEventListener('resize', function(){\n    clearTimeout(rt);\n    rt = setTimeout(function(){ size(); if (still) drawStatic(); onScroll(); }, 150);\n  });\n\n  /* ---------- terminal typing ---------- */\n  var lines = Array.prototype.slice.call(document.querySelectorAll('#termBody .tl'));\n  var html = lines.map(function(l){ return l.innerHTML; });\n  var typingTimer = null, typingDone = false;\n  var caret = document.createElement('span'); caret.className = 'caret'; caret.setAttribute('aria-hidden','true');\n\n  function finishTyping(){\n    clearTimeout(typingTimer);\n    lines.forEach(function(l, i){ l.innerHTML = html[i]; l.style.visibility = ''; });\n    lines[lines.length - 1].appendChild(caret);\n    typingDone = true;\n  }\n  function startTyping(){\n    lines.forEach(function(l){ l.style.visibility = 'hidden'; });\n    var li = 0;\n    function nextLine(){\n      if (still) { finishTyping(); return; }\n      if (li >= lines.length) { lines[lines.length - 1].appendChild(caret); typingDone = true; return; }\n      var el = lines[li], full = html[li];\n      var tmp = document.createElement('div'); tmp.innerHTML = full;\n      var text = tmp.textContent, ci = 0, isPrompt = el.classList.contains('p');\n      el.style.visibility = ''; el.textContent = '';\n      el.appendChild(caret);\n      function tick(){\n        if (still) { finishTyping(); return; }\n        ci++;\n        el.textContent = text.slice(0, ci); el.appendChild(caret);\n        if (ci \u003c text.length) typingTimer = setTimeout(tick, isPrompt ? 42 : 22);\n        else { el.innerHTML = full; li++; typingTimer = setTimeout(nextLine, isPrompt ? 520 : 160); }\n      }\n      typingTimer = setTimeout(tick, isPrompt ? 200 : 60);\n    }\n    typingTimer = setTimeout(nextLine, 900);\n  }\n\n  /* ---------- scroll-linked ---------- */\n  var bar = document.getElementById('top-bar');\n  var prog = document.getElementById('progress');\n  var heroGrid = document.getElementById('heroGrid');\n  var tracks = document.querySelectorAll('.ticker-track');\n  var rail = document.querySelector('.rail');\n  var railFill = document.getElementById('railFill');\n  var steps = document.querySelectorAll('.step');\n  var ticking = false;\n\n  function onScroll(){\n    ticking = false;\n    var y = window.scrollY || window.pageYOffset, vh = window.innerHeight;\n    var max = document.documentElement.scrollHeight - vh;\n    prog.style.transform = 'scaleX(' + (max > 0 ? y / max : 0).toFixed(4) + ')';\n    bar.classList.toggle('scrolled', y > 20);\n\n    if (!still) {\n      var hp = Math.min(1, y / vh);\n      cv.style.opacity = (0.9 * (1 - hp * .9)).toFixed(3);\n      heroGrid.style.transform = 'translate3d(0,' + (hp * 60).toFixed(1) + 'px,0)';\n      heroGrid.style.opacity = (1 - hp * .6).toFixed(3);\n      tracks.forEach(function(t){\n        var r = t.getBoundingClientRect(), dir = +t.getAttribute('data-dir');\n        var off = (r.top + r.height / 2 - vh / 2) * .35 * dir;\n        t.style.transform = 'translate3d(' + (off - 200).toFixed(1) + 'px,0,0)';\n      });\n    } else {\n      cv.style.opacity = ''; heroGrid.style.transform = ''; heroGrid.style.opacity = '';\n    }\n\n    var rr = rail.getBoundingClientRect();\n    var mark = vh * .62;\n    var p = Math.max(0, Math.min(1, (mark - rr.top) / rr.height));\n    railFill.style.transform = 'scaleY(' + p.toFixed(4) + ')';\n    steps.forEach(function(s){\n      var d = s.querySelector('.dot').getBoundingClientRect();\n      s.classList.toggle('lit', d.top + d.height / 2 \u003c mark);\n    });\n  }\n  window.addEventListener('scroll', function(){\n    if (!ticking) { ticking = true; requestAnimationFrame(onScroll); }\n  }, {passive:true});\n\n  /* ---------- card spotlight ---------- */\n  document.querySelectorAll('.card').forEach(function(c){\n    c.addEventListener('pointermove', function(e){\n      var r = c.getBoundingClientRect();\n      c.style.setProperty('--mx', (e.clientX - r.left) + 'px');\n      c.style.setProperty('--my', (e.clientY - r.top) + 'px');\n    });\n  });\n\n  /* ---------- flow switch ---------- */\n  var sw = document.getElementById('extSwitch');\n  var flow = document.getElementById('flowDiagram');\n  var note = document.getElementById('flowNote');\n  var st = document.getElementById('extState');\n  var offText = note.innerHTML;\n  var onText = '検索・拡張機能・同期・更新確認などの機能や設定によっては、\u003cstrong>外部との通信が発生\u003c/strong>します。「ローカルで動かしている＝自動的に完全な秘密保持」ではありません。';\n  sw.addEventListener('click', function(){\n    var on = sw.getAttribute('aria-checked') !== 'true';\n    sw.setAttribute('aria-checked', String(on));\n    flow.classList.toggle('on', on);\n    st.textContent = on ? 'ON' : 'OFF';\n    note.innerHTML = on ? onText : offText;\n  });\n\n  /* ---------- checklist ---------- */\n  var chks = document.querySelectorAll('.chk');\n  var tallyNum = document.getElementById('tallyNum');\n  var ring = document.getElementById('tallyRing');\n  var C = 2 * Math.PI * 26;\n  ring.style.strokeDasharray = C.toFixed(1);\n  function tally(){\n    var n = 0; chks.forEach(function(c){ if (c.checked) n++; });\n    tallyNum.textContent = n;\n    ring.style.strokeDashoffset = (C * (1 - n / chks.length)).toFixed(1);\n  }\n  chks.forEach(function(c){ c.addEventListener('change', tally); });\n  tally();\n\n  /* ---------- motion control ---------- */\n  function applyMotion(){\n    root.classList.toggle('still', still);\n    btn.setAttribute('aria-pressed', String(still));\n    btnLbl.textContent = still ? '動きを再開' : '動きを止める';\n    btnSr.textContent = still ? 'アニメーションを再開する' : 'アニメーションを止める';\n    if (still) {\n      if (raf) { cancelAnimationFrame(raf); raf = 0; }\n      if (!typingDone) finishTyping();\n      drawStatic();\n    } else {\n      startLoop();\n    }\n    onScroll();\n  }\n  btn.addEventListener('click', function(){ still = !still; applyMotion(); });\n  var mqHandler = function(e){ still = e.matches; applyMotion(); };\n  if (mq.addEventListener) mq.addEventListener('change', mqHandler);\n  else if (mq.addListener) mq.addListener(mqHandler);\n\n  if (still) { finishTyping(); } else { startTyping(); }\n  applyMotion();\n})();\n\u003c/script>\n\u003c/body>\n\u003c/html>"};
